import assert from "node:assert/strict";
import { openStore, closeStores, driveThrough, envelope, send, PROJECT_ID, GOAL_ID } from "./apps/daemon/src/bootstrap/bootstrap-test-fixtures.js";
import { createAffordancePort } from "./apps/daemon/src/http/affordance-read.js";
import { readDurableLedger, versionOf } from "./apps/daemon/src/bootstrap/bootstrap-ledger.js";
import { deployTargetAggregateId } from "./apps/daemon/src/deployment/deploy-target-contracts.js";
process.env.MOE_APPROVAL_MODE = "SPEED";
process.env.MOE_SPEED_MODE_DELAY_MS = "0";
const store = openStore();
try {
  driveThrough(store, "repository.publish");
  let mint = 0;
  const port = createAffordancePort({store, projectId: PROJECT_ID, mintId: () => "probe-"+(++mint)});
  const before = port.readSurface();
  assert.equal(before.outcome, "SURFACE");
  const initial = before.nextAllowedCommands.filter(x => x.commandKind === "deployment.set_target");
  const payload = {environment:"preview",network:"probe-net",sshTarget:null,url:null};
  const bind = send(store, envelope("deployment.set_target",0,payload,"probe-first"));
  assert.equal(bind.ok,true);
  const after = port.readSurface();
  assert.equal(after.outcome,"SURFACE");
  const ledger = readDurableLedger(store,PROJECT_ID);
  const proposedKey = "deploy:"+GOAL_ID;
  const proposedVersion = versionOf(ledger,proposedKey);
  const writeKey = deployTargetAggregateId(PROJECT_ID,"preview");
  const rebound = send(store,envelope("deployment.set_target",proposedVersion,{...payload,network:"probe-next"},"probe-next"));
  assert.equal(rebound.ok,false);
  assert.equal(rebound.code,"EXPECTED_VERSION_CONFLICT");
  assert.equal(rebound.refusedBy,"DURABLE_STORE");
  console.log(JSON.stringify({initial,afterOffers:after.nextAllowedCommands.filter(x=>x.commandKind==="deployment.set_target"),proposedKey,proposedVersion,writeKey,writeVersion:store.getAggregateVersion(writeKey),rebind:{code:rebound.code,layer:rebound.refusedBy}},null,2));
} finally { closeStores(); }
